import {VERSION,STORAGE_KEY,STEPS,DATA,A,B,mean,quantile,sampleSD,lossFrequency,correlation,resample,PRACTICE,ASSESSMENTS,check,grade,freshState,restoreState,invalidate,labEvidence} from './model.mjs';
import {LESSONS,SOURCES} from './lessons.mjs';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=freshState(),storageOK=true,page='start';try{state=restoreState(localStorage.getItem(STORAGE_KEY));}catch{storageOK=false;}
const value=id=>state.fields[id]||'',fmt=n=>n===null?'Undefined':Number(n).toFixed(3),field=(id,label,area=false,defaultValue='')=>`<label class="field" for="${id}">${label}</label>${area?`<textarea id="${id}" data-save>${esc(state.fields[id]??defaultValue)}</textarea>`:`<input id="${id}" data-save type="number" step="any" value="${esc(state.fields[id]??defaultValue)}">`}`,box=(id,label)=>`<label class="option"><input id="${id}" type="checkbox" data-save ${value(id)==='yes'?'checked':''}><span>${label}</span></label>`;
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}$('#save-state').textContent=storageOK?'Saved on this device':'Saving unavailable · export before leaving';nav();}
function nav(){const n=STEPS.filter(([id])=>state.done[id]).length;$('#progress-label').textContent=`${n} of 8 steps complete`;$('#progress-percent').textContent=Math.round(n/8*100)+'%';$('#progress').value=n;$('#navigation').innerHTML=STEPS.map(([id,t,m],i)=>`<a href="#${id}" ${id===page?'aria-current="step"':''} class="${state.done[id]?'done':''}"><span class="step-icon" aria-hidden="true">${state.done[id]?'✓':i+1}</span><span>${t}<small>${m} min${state.done[id]?' · complete':''}</small></span></a>`).join('');}
function feedback(id,text,error=false){const el=$('#'+id);el.textContent=text;el.className='feedback'+(error?' error':'');el.tabIndex=-1;el.focus();}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const table=()=>`<div class="table-wrap"><table><caption>Original hypothetical monthly total returns, percentage units. Six aligned months; no fees or taxes.</caption><thead><tr><th scope="col">Month</th><th scope="col">Asset A (%)</th><th scope="col">Asset B (%)</th></tr></thead><tbody>${DATA.map(r=>`<tr><th scope="row">${r.date}</th><td>${r.a}</td><td>${r.b}</td></tr>`).join('')}</tbody></table></div><p><a href="returns.csv" download>Download the six-month CSV</a></p>`;
const header=(title,lead)=>`<div class="eyebrow">Chapter 04 · ${STEPS.find(s=>s[0]===page)?.[2]} minutes</div><h1>${title}</h1><p class="lead">${lead}</p>`;
function start(){return header('Describe the<br><em>evidence.</em>','A short return history can look persuasive. Learn what its summaries say, what they omit, and why a sample is not a promise.')+`<div class="pill-row"><span class="pill">180-minute core</span><span class="pill">No installation</span><span class="pill">Optional Python +45 min</span></div><section class="panel"><h2>Your independent learning setup</h2><p>This chapter stands alone. Bring a calculator, paper and the six supplied hypothetical monthly returns. You need addition, division, squares and square roots; no statistical background is assumed. All explanations, checks and revision prompts are here. There is no instructor dependency or time limit.</p><ol><li>Read a worked example, predict, calculate a new case, check and revise.</li><li>Keep returns in percentage units: 2 means 2%, not 0.02. For probabilities use 0–1: .25 means 25%. SD of percentage-unit returns is in percentage points.</li><li>For a square, multiply a number by itself. For √4 use the square-root key: 2. A squared negative deviation becomes positive.</li><li>Use <a href="guide.html">the complete text/paper route</a> at any time. Progress and all attempts save locally; Export downloads a record, not a sync/restore file.</li></ol>${box('setup','I can find the data, calculator, hints, Export and Privacy & reset.')}<button data-action="setup">Confirm setup & continue →</button><div id="feedback-start" class="feedback" role="status"></div></section><section class="panel"><h2>Four outcomes, one cautious decision</h2><p>CH4-01: count an event and complement. CH4-02: explain mean and median. CH4-03: compute sample spread and a declared quantile. CH4-04: interpret aligned correlation and sampling uncertainty. Your final task is a statistics card that states the convention, a checked number, and a limit on inference.</p>${table()}<p>The dates label invented monthly pairs, not retrieved market prices. No company or product performance is represented. Do not treat this sample as a forecast or investment recommendation.</p></section>`;}
function practice(step){const l=LESSONS[step];return header(l.title,l.objective)+l.body+table()+`<section class="panel"><h2>Try, check, explain, revise</h2><p>Use a calculator. Enter numbers only: no % sign. Round to two decimals or keep more precision. Choice questions use the stated number.</p>${PRACTICE[step].map((q,i)=>`<div class="practice-item">${field(q.id,q.title)}<div class="actions"><button data-action="practice" data-id="${q.id}">Check task ${i+1}</button><details><summary>Hint</summary><p>${q.hint}</p></details></div><div id="feedback-${q.id}" class="feedback" role="status">${state.checked[q.id]?'Correct. '+q.hint:''}</div></div>`).join('')}<h3>Explain and revise</h3><p>${l.reflection}</p>${field(step+'Reflection','My explanation, check or correction',true)}${box(step+'Criteria',l.criteria)}<p class="mini">Self-review checks reasoning; the app checks numerical answers and that you supplied at least 30 characters. Prose quality is not automatically graded.</p><button data-action="save-step">Save this lesson</button><div id="feedback-step" class="feedback" role="status">${state.done[step]?'Lesson evidence saved.':''}</div></section>`;}
function runResult(run){const bins=Array.from({length:10},(_,i)=>{const lo=i-3;return {lo,hi:lo+1,count:run.rows.filter(r=>r.mean>=lo&&(i===9?r.mean<=lo+1:r.mean<lo+1)).length};}),max=Math.max(...bins.map(b=>b.count),1);return `<h3>Run with seed ${run.seed}: 100 resampled means</h3><p>Original sample mean ${fmt(mean(A))}%; average resampled mean ${fmt(mean(run.rows.map(r=>r.mean)))}%. Each replicate samples six rows with replacement. A row may appear repeatedly, or not at all.</p><div class="histogram" role="img" aria-label="Histogram of resampled means; exact bin counts and replicate values follow.">${bins.map(b=>`<span style="height:${Math.max(2,b.count/max*120)}px" aria-hidden="true"></span>`).join('')}</div><div class="table-wrap"><table><caption>Histogram bin counts, equal one-percentage-point widths. Left endpoint included; right excluded except last.</caption><thead><tr><th scope="col">Mean return interval (%)</th><th scope="col">Count</th></tr></thead><tbody>${bins.map(b=>`<tr><th scope="row">${b.lo} to ${b.hi}${b.hi===7?' inclusive':''}</th><td>${b.count}</td></tr>`).join('')}</tbody></table></div><details><summary>All 100 replicate values and their source rows</summary><div class="table-wrap run-list"><table><caption>Indices are one-based rows in the original A table, in sampling order. Repeats are intentional.</caption><thead><tr><th scope="col">Replicate</th><th scope="col">Source rows</th><th scope="col">Sampled returns (%)</th><th scope="col">Mean (%)</th></tr></thead><tbody>${run.rows.map(r=>`<tr><th scope="row">${r.replicate}</th><td>${r.indices.map(i=>i+1).join(', ')}</td><td>${r.values.join(', ')}</td><td>${fmt(r.mean)}</td></tr>`).join('')}</tbody></table></div></details>`;}
function lab(){const r=state.runs.at(-1);return header('A different sample.<br>A different summary.','CH4-05 · Explore sampling sensitivity using seeded resampling; explain why simulation does not supply new market evidence.')+`<p>Sampling uncertainty means a statistic can differ when the observations differ. A <strong>bootstrap</strong> resamples the observed rows, with replacement, into samples of the same size. We repeat this 100 times and calculate each mean. This is a demonstration of sensitivity conditional on six invented observations, <strong>not a validated confidence interval or future-return distribution</strong>.</p><p>Sampling rows as exchangeable independent observations is a simplifying assumption. Real monthly returns can be dependent and their distribution can change. More simulated rows do not create more independent original evidence. Individual resampled returns can only be one of the six source values; resampled means may differ.</p><p>The generator is the fixed 32-bit linear congruential rule z ← (1664525z + 1013904223) mod 2³²; uniform z/2³² selects floor(u×6). Same seed and inputs reproduce exactly in this JavaScript implementation. The generator is for teaching, not security or market modelling.</p><section class="panel"><h2>1. Predict and run</h2>${field('prediction','Predict whether every resampled mean will equal 1%. Explain why or why not.',true)}${field('seed','Whole-number seed, 1–999999',false,'42')}<div class="actions"><button data-action="run">Run 100 resamples</button><button data-action="seed-default" class="secondary">Reset seed to 42</button></div><div id="feedback-run" class="feedback" role="status"></div>${r?runResult(r):'<p>Your histogram and complete replicate table appear after the first run.</p>'}</section><section class="panel"><h2>2. Check, change, revise</h2><p>Verify the first replicate of your latest run by adding its six sampled returns and dividing by six. Then change only the seed and run again. Re-run an earlier seed to check reproducibility. Every run stays in the log.</p>${field('hand','First replicate mean of latest run (%)')}<button data-action="hand">Check my hand calculation</button><div id="feedback-hand" class="feedback" role="status">${value('handVerified')==='yes'?'Latest first replicate checked.':''}</div>${field('labReflection','Compare seeds, revise your prediction, and state the independence and tiny-sample limitations (at least 50 characters).',true)}${box('labCriteria','I compared two seeds, distinguished original observations from repetitions, and explained why this is not a forecast or validated interval.')}<details><summary>Review your explanation</summary><p>Individual replicate means need not equal 1%. The distribution changes when random draws change. Repeating one seed exactly reproduces that run; a different seed need not give identical results. All draws still reuse the same six invented observations. Independence and stable-distribution assumptions are doubtful for many market histories. Do not describe more repetitions as new financial evidence.</p></details><div class="actions"><button data-action="save-lab">Save lab evidence</button><button data-action="csv" class="secondary">Export all replicates (CSV)</button></div><div id="feedback-lab" class="feedback" role="status">${state.done.lab?'Lab evidence saved.':''}</div></section><section class="panel"><h2>All runs retained</h2><ol>${state.runs.map(r=>`<li>Seed ${r.seed}, ${esc(r.time)}; prediction: ${esc(r.prediction)}</li>`).join('')||'<li>No runs yet.</li>'}</ol><p>Reset seed keeps the log. Privacy & reset deletes only this chapter’s browser record.</p></section>`;}
function assessment(){const a=state.attempts.at(-1);return header('Use a fresh case.','Independent transfer · Attempt all eight questions before checking. Then act on the feedback and resubmit if needed.')+`<section class="panel"><p>No countdown. Calculator and paper allowed. Work independently before revealing feedback. Pass: at least 7 of 8, including all four critical conventions: sample SD, undefined correlation, resampling limits, and date alignment. This is formative self-learning, not a secure exam or credential.</p>${ASSESSMENTS.map(q=>field('quiz-'+q.id,q.title)).join('')}<button data-action="grade">Check independent attempt</button><div id="feedback-assessment" class="feedback" role="status">${a?`${a.score}/8 on last submitted attempt. ${a.passed?'Numerical and critical criteria met.':'Revise and submit again.'} ${value('quizDirty')==='yes'?'Answers or response have changed: resubmit current answers.':''}`:''}</div><details><summary>Previous attempt log (${state.attempts.length})</summary><ol>${state.attempts.map(a=>`<li>${esc(a.time)}: ${a.score}/8; ${a.passed?'criteria met':'revisit'}${a.revision?' · response saved':''}</li>`).join('')}</ol></details><h2>Respond to feedback</h2>${field('revision','Describe one specific correction or verification and its reason (at least 30 characters).',true)}<button data-action="revision">Save feedback response</button><div id="feedback-revision" class="feedback" role="status">${state.done.assessment?'Independent evidence and response saved.':''}</div></section>`;}
function finish(){return header('Keep a statistics card.','Explain the convention, a checked result and the limit of the evidence. Save a tool for the next chapter.')+`<section class="panel">${field('cardMethod','My convention: event boundary, sample SD, quantile rule or date pairing (30+ characters).',true)}${field('cardCheck','My checked number, units and a hand calculation (30+ characters).',true)}${field('cardLimit','My inference limit, dependence issue or next data check (30+ characters).',true)}${box('cardCriteria','I checked my arithmetic and described a meaningful limitation, rather than a forecast.')}<p>The app checks completion, not the substantive quality of prose. Compare your card with the criteria below.</p><details><summary>Card self-review rubric</summary><p>Method: explicit convention and inputs. Check: reproducible number with correct units. Limit: what the tiny sample cannot justify and what more evidence would be needed. Revise any claim of causation, guaranteed future probabilities or validated confidence intervals.</p></details><button data-action="card">Save my statistics card</button><div id="feedback-finish" class="feedback" role="status"></div><h2>Evidence checklist</h2><ul>${STEPS.map(([id,t])=>`<li>${state.done[id]?'Complete':'To do'}: ${t}</li>`).join('')}</ul><button data-action="export" class="secondary">Export my complete chapter record</button></section><section class="panel"><h2>Sources and next steps</h2><ul>${SOURCES.map(([t,u])=>`<li><a href="${u}">${t}</a></li>`).join('')}<li><a href="https://www.itl.nist.gov/div898/software/dataplot/refman1/ch2/bootstra.pdf">NIST: resampling with replacement and seed</a></li></ul><p>Primary sources checked 31 October 2026. All numerical data and worked tasks are original hypothetical teaching material. Core pacing is proposed, not learner validated. Full screen-reader testing and a human learning pilot remain pending.</p><p><a href="../python/?chapter=4#ch4-summary">Optional: consolidate in Python (+45 minutes)</a>. Three scripts cover summaries, quantiles and aligned correlation; separate Python progress and setup time. This is beyond the 30-hour noncoding core.</p></section>`;}
function render(focus=true){const next=location.hash.slice(1)||'start';if(next==='lesson'&&$('#lesson').children.length){$('#lesson').focus();return;}page=next;if(!STEPS.some(s=>s[0]===page))page='start';const i=STEPS.findIndex(s=>s[0]===page);$('#lesson').innerHTML=(LESSONS[page]?practice(page):({start,lab,assessment,finish}[page])())+`<div class="bottom-nav">${i?`<a href="#${STEPS[i-1][0]}">← Previous step</a>`:'<a href="../chapter-03/">← Chapter 3</a>'}${i<7?`<a href="#${STEPS[i+1][0]}">${STEPS[i+1][1]}</a>`:'<a href="../chapter-05/">Continue to Chapter 5</a>'}</div>`;nav();if(focus)$('#lesson').focus();}
document.addEventListener('input',e=>{if(!e.target.matches('[data-save]'))return;const id=e.target.id;state.fields[id]=e.target.type==='checkbox'?(e.target.checked?'yes':''):e.target.value;invalidate(state,id);persist();});
document.addEventListener('click',e=>{if(e.target.closest('a.skip')){e.preventDefault();$('#lesson').focus();return;}const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;
if(action==='export'){download('qf-chapter-04-record.json',JSON.stringify({...state,exported:new Date().toISOString()},null,2));$('#announcement').textContent='Chapter 4 record exported.';}
if(action==='setup'){if(value('setup')!=='yes')return feedback('feedback-start','Confirm the setup checklist first.',true);state.done.start=true;persist();location.hash='probability';}
if(action==='practice'){const q=Object.values(PRACTICE).flat().find(q=>q.id===e.target.dataset.id),ok=check(q,value(q.id));state.checked[q.id]=ok;state.practiceAttempts.push({id:q.id,raw:value(q.id),correct:ok,time:new Date().toISOString()});delete state.done[page];persist();feedback('feedback-'+q.id,ok?'Correct. '+q.hint:'Revisit. '+q.hint+' Use the stated units, revise, and check again.',!ok);}
if(action==='save-step'){if(!PRACTICE[page].every(q=>state.checked[q.id]&&check(q,value(q.id)))||value(page+'Reflection').trim().length<30||value(page+'Criteria')!=='yes')return feedback('feedback-step','Check both tasks correctly, write a specific explanation (30+ characters), and confirm your self-review.',true);state.done[page]=true;persist();feedback('feedback-step','Lesson evidence saved. Your prose is self-reviewed against the stated criteria.');}
if(action==='seed-default'){state.fields.seed='42';delete state.done.lab;persist();render();}
if(action==='run'){if(value('prediction').trim().length<20)return feedback('feedback-run','Write a prediction with a reason (at least 20 characters) before running.',true);try{const seed=Number(state.fields.seed??42),rows=resample(seed);state.runs.push({seed,rows,prediction:value('prediction'),time:new Date().toISOString()});state.fields.hand='';state.fields.handVerified='';delete state.done.lab;persist();render(false);feedback('feedback-run','Resampling run recorded. Read the table and verify the first replicate.');}catch(err){feedback('feedback-run',err.message,true);}}
if(action==='hand'){const r=state.runs.at(-1),ok=r&&check({answer:r.rows[0].mean,tolerance:.011},value('hand'));state.fields.handVerified=ok?'yes':'';delete state.done.lab;persist();feedback('feedback-hand',ok?'Correct. You verified the latest run’s first replicate.':'Use the latest first replicate’s six sampled values, including repeats. Add them and divide by six; then revise.',!ok);}
if(action==='save-lab'){if(!labEvidence(state))return feedback('feedback-lab','Run two distinct seeds with the current seed and prediction matching the latest run, verify its first replicate, write a 50+ character comparison with limitations, and confirm self-review.',true);state.done.lab=true;persist();feedback('feedback-lab','Lab evidence saved. Repetitions are not additional original observations.');}
if(action==='csv'){if(!state.runs.length)return feedback('feedback-lab','Run a resampling experiment first.',true);download('qf-chapter-04-all-resamples.csv','run,seed,replicate,source_rows,sampled_returns_pct,mean_pct\n'+state.runs.flatMap((run,i)=>run.rows.map(r=>`${i+1},${run.seed},${r.replicate},"${r.indices.map(j=>j+1).join(';')}","${r.values.join(';')}",${r.mean}`)).join('\n'),'text/csv');}
if(action==='grade'){const answers=Object.fromEntries(ASSESSMENTS.map(q=>[q.id,value('quiz-'+q.id)]));if(ASSESSMENTS.some(q=>answers[q.id].trim()===''))return feedback('feedback-assessment','Answer all eight questions before checking. No time limit applies.',true);const result=grade(answers);state.attempts.push({...result,answers,time:new Date().toISOString()});state.fields.quizDirty='';state.fields.revision='';delete state.done.assessment;persist();feedback('feedback-assessment',`${result.score}/8. ${result.passed?'Criteria met; now record a feedback response.':'Revise and resubmit; all four critical conventions must be correct.'} `+ASSESSMENTS.map(q=>`${q.id}: ${check(q,answers[q.id])?'Correct':'Revisit'} — ${q.hint}`).join(' '),!result.passed);}
if(action==='revision'){const a=state.attempts.at(-1);if(!a||!ASSESSMENTS.every(q=>a.answers[q.id]===value('quiz-'+q.id)))return feedback('feedback-revision','Submit your current answers before saving their feedback response.',true);if(value('revision').trim().length<30)return feedback('feedback-revision','Describe a specific correction or verification (at least 30 characters).',true);a.revision=value('revision');state.fields.quizDirty='';if(a.passed)state.done.assessment=true;persist();feedback('feedback-revision',a.passed?'Feedback response saved. Independent check complete.':'Response saved. Revise answers and resubmit to meet the criteria.');}
if(action==='card'){if(!['cardMethod','cardCheck','cardLimit'].every(id=>value(id).trim().length>=30)||value('cardCriteria')!=='yes')return feedback('feedback-finish','Complete all three 30+ character fields and confirm your self-review.',true);state.done.finish=true;persist();render(false);feedback('feedback-finish',STEPS.every(([id])=>state.done[id])?'Chapter complete. Export your evidence and card for your records.':'Statistics card saved. Use the checklist to complete any missing evidence.');}
});
$('#chapter-select').addEventListener('change',e=>{location.href=e.target.value==='1'?'../index.html':`../chapter-0${e.target.value}/`;});$('#privacy-button').onclick=()=>$('#privacy-dialog').showModal();$('#close-privacy').onclick=()=>$('#privacy-dialog').close();$('#reset-progress').onclick=()=>{if(!confirm('Delete only Chapter 4 browser progress and runs? Other chapters and downloaded files remain.'))return;state=freshState();try{localStorage.removeItem(STORAGE_KEY);}catch{}$('#privacy-dialog').close();location.hash='start';render();$('#announcement').textContent='Chapter 4 reset.';};window.addEventListener('hashchange',()=>render());render(false);
